<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{ElMessage}from'element-plus';import{ArrowLeft,Plus,Trash2,GripVertical,Save,Upload}from'lucide-vue-next';import{api}from'../api';import{useAppStore}from'../stores/app';import type{Output,Upstream}from'../types';import{parseBulkUpstreams}from'../utils';
const DEFAULT_TEMPLATE='{index}|{flag}|{name}|{traffic}|{reset}';const route=useRoute(),router=useRouter(),store=useAppStore(),saving=ref(false),bulk=ref(''),renameSample=ref('DMIT-US-04-HK-BoilHKT-Home|📊500.00GB|⌛25D');const editing=computed(()=>!!route.params.id);const model=reactive({name:'我的订阅组',note:'',interval_minutes:30,enabled:true,rename_mode:'passthrough' as 'passthrough'|'smart',rename_ignore:'DMIT-US',rename_template:DEFAULT_TEMPLATE,upstreams:[{name:'上游 1',url:'',enabled:true,rename_policy:'inherit',rename_ignore:'',rename_template:DEFAULT_TEMPLATE}]as Upstream[],outputs:[{client_type:'mihomo',name:'我的订阅',slug:'mihomo',update_interval_minutes:60,enabled:true}]as Output[]})
onMounted(async()=>{if(!store.settings)await store.load();if(editing.value){Object.assign(model,await api(`/api/subscriptions/${route.params.id}`))}else{const copy=sessionStorage.getItem('duplicateGroup');if(copy){Object.assign(model,JSON.parse(copy));sessionStorage.removeItem('duplicateGroup')}else{model.interval_minutes=store.settings!.default_refresh_interval_minutes;model.outputs[0].client_type=store.settings!.default_client_type;model.outputs[0].slug=store.settings!.default_client_type;model.outputs[0].update_interval_minutes=store.settings!.default_output_interval_minutes}}})
function addUpstream(){model.upstreams.push({name:`上游 ${model.upstreams.length+1}`,url:'',enabled:true,rename_policy:'inherit',rename_ignore:'',rename_template:DEFAULT_TEMPLATE,last_bytes:0,node_count:0,filtered_count:0,used_cache:false})}function addOutput(){const base=store.settings?.default_client_type||'mihomo';let slug=base,n=2;while(model.outputs.some(x=>x.slug===slug))slug=base+n++;model.outputs.push({client_type:base,name:model.name,slug,update_interval_minutes:store.settings?.default_output_interval_minutes||60,enabled:true})}
function parseBulk(){const parsed=parseBulkUpstreams(bulk.value,model.upstreams.length+1);for(const item of parsed)model.upstreams.push({...item,rename_policy:'inherit',rename_ignore:'',rename_template:DEFAULT_TEMPLATE,last_bytes:0,node_count:0,filtered_count:0,used_cache:false});bulk.value='';ElMessage.success(`已加入 ${parsed.length} 条上游`)}
function moveUpstream(index:number,delta:number){const next=index+delta;if(next<0||next>=model.upstreams.length)return;const[item]=model.upstreams.splice(index,1);model.upstreams.splice(next,0,item)}
function flag(code:string){const c=(code.toUpperCase()==='UK'?'GB':code.toUpperCase());return/^[A-Z]{2}$/.test(c)?[...c].map(x=>String.fromCodePoint(127397+x.charCodeAt(0))).join(''):''}
function cleanNumber(value:string){return value.includes('.')?value.replace(/0+$/,'').replace(/\.$/,''):value}
const renamePreview=computed(()=>{const original=renameSample.value.trim(),segments=original.split(/[|｜]/).map(x=>x.trim());let core=segments[0]||original,traffic='',reset='';for(const part of segments.slice(1)){const t=part.match(/(?:📊\s*|流量\s*[:：]?\s*)?(\d+(?:\.\d+)?)\s*([KMGT]B)\b/i);if(t&&!traffic)traffic=cleanNumber(t[1])+t[2].toUpperCase();const d=part.match(/(?:⌛|⏳|重置\s*[:：]?)?\s*(\d+)\s*(?:D|天)\b/i);if(d&&!reset)reset=String(Number(d[1]))+'D'}const ignores=model.rename_ignore.split(/[\r\n,，;；]+/).map(x=>x.trim().replace(/^[-_| ]+|[-_| ]+$/g,'')).filter(Boolean).sort((a,b)=>b.length-a.length);for(const prefix of ignores){if(core.toLowerCase()===prefix.toLowerCase()){core='';break}if(core.toLowerCase().startsWith(prefix.toLowerCase())&&/[-_ |]/.test(core.charAt(prefix.length))){core=core.slice(prefix.length).replace(/^[-_| ]+/,'');break}}let index='',country='',countryFlag='';const i=core.match(/^(\d{1,3})(?:[-_\s]+|$)/);if(i){index=i[1];core=core.slice(i[0].length)}const c=core.match(/^([A-Za-z]{2})(?:[-_\s]+|$)/);if(c){country=c[1].toUpperCase();countryFlag=flag(country);core=core.slice(c[0].length)}const values:any={index,flag:countryFlag,country,name:core.replace(/^[-_| ]+|[-_| ]+$/g,'')||original,traffic,reset,source:'上游名称',original};return model.rename_template.replace(/\{([a-z_]+)\}/gi,(_,key)=>values[key.toLowerCase()]||'').replace(/\|(?:\s*\|)+/g,'|').replace(/-{2,}/g,'-').replace(/^[-_| /·]+|[-_| /·]+$/g,'')||original})
async function save(){saving.value=true;try{const payload={...model,upstreams:model.upstreams.map(({id,name,url,enabled,rename_policy,rename_ignore,rename_template})=>({id,name,url,enabled,rename_policy,rename_ignore,rename_template})),outputs:model.outputs.map(({id,client_type,name,slug,update_interval_minutes,enabled})=>({id,client_type,name,slug,update_interval_minutes,enabled}))};await api(editing.value?`/api/subscriptions/${route.params.id}`:'/api/subscriptions',{method:editing.value?'PUT':'POST',body:JSON.stringify(payload)});await store.loadGroups();ElMessage.success('订阅组已保存');router.push('/groups')}catch(e:any){ElMessage.error(e.message)}finally{saving.value=false}}
</script>
<template><section class="page editor-page"><header class="page-head"><div><button class="back" @click="router.back()"><ArrowLeft/></button><p class="eyebrow">SUBSCRIPTION GROUP</p><h1>{{editing?'编辑订阅组':'新建订阅组'}}</h1><p>一组上游只抓取一次，然后生成多个客户端输出。</p></div><div class="head-actions"><el-button @click="router.back()">取消</el-button><el-button type="primary" :loading="saving" @click="save"><Save/>保存订阅组</el-button></div></header>
<nav class="editor-steps"><span>01 基本信息</span><i></i><span>02 上游订阅</span><i></i><span>03 节点改名</span><i></i><span>04 客户端输出</span></nav>
<div class="editor-layout"><div class="editor-main"><section class="panel form-section"><div class="section-head"><span>01</span><div><h2>基本信息</h2><p>用于识别和调度这个独立订阅组。</p></div></div><div class="form-grid"><label>订阅组名称<el-input v-model="model.name" size="large"/></label><label>自动拉取间隔<el-select v-model="model.interval_minutes" size="large"><el-option label="10 分钟" :value="10"/><el-option label="30 分钟" :value="30"/><el-option label="1 小时" :value="60"/><el-option label="3 小时" :value="180"/><el-option label="6 小时" :value="360"/><el-option label="24 小时" :value="1440"/></el-select></label><label class="wide">备注<el-input v-model="model.note" size="large" placeholder="例如：三个机场混合，主要给 Clash Verge 使用"/></label></div><el-switch v-model="model.enabled" active-text="启用定时刷新和公开订阅地址"/></section>
<section class="panel form-section"><div class="section-head"><span>02</span><div><h2>上游订阅</h2><p>支持混合输入；每条上游可继承或覆盖组级改名规则。</p></div><el-button @click="addUpstream"><Plus/>添加上游</el-button></div><div class="structured-list upstream-config-list"><article v-for="(up,i) in model.upstreams" :key="up.id||i"><div class="upstream-main-row"><GripVertical class="grip"/><div class="list-fields"><label>名称<el-input v-model="up.name"/></label><label class="url-field">订阅 URL<el-input v-model="up.url" type="password" show-password placeholder="https://…"/></label></div><el-switch v-model="up.enabled"/><div class="sort-buttons"><button :disabled="i===0" title="上移" @click="moveUpstream(i,-1)">↑</button><button :disabled="i===model.upstreams.length-1" title="下移" @click="moveUpstream(i,1)">↓</button></div><button class="icon-danger" title="删除" @click="model.upstreams.splice(i,1)"><Trash2/></button></div><el-collapse class="upstream-rule"><el-collapse-item title="单独设置该上游的改名规则"><div class="form-grid"><label>改名策略<el-select v-model="up.rename_policy"><el-option label="继承订阅组规则" value="inherit"/><el-option label="独立智能规则" value="smart"/><el-option label="原样透传" value="passthrough"/></el-select></label><template v-if="up.rename_policy==='smart'"><label>忽略前缀<el-input v-model="up.rename_ignore" placeholder="DMIT-US"/></label><label class="wide">改名模板<el-input v-model="up.rename_template"/></label></template></div></el-collapse-item></el-collapse></article></div><el-collapse class="bulk"><el-collapse-item title="批量粘贴多个订阅链接"><el-input v-model="bulk" type="textarea" :rows="6" placeholder="每行一个 URL，也支持：机场名称 | https://…"/><el-button class="bulk-button" @click="parseBulk"><Upload/>解析并加入当前组</el-button></el-collapse-item></el-collapse></section>
<section class="panel form-section"><div class="section-head"><span>03</span><div><h2>节点自动改名</h2><p>改名发生在去重之后，并透传到本组的全部下游输出。</p></div></div><el-radio-group v-model="model.rename_mode"><el-radio-button value="passthrough">原样透传</el-radio-button><el-radio-button value="smart">智能规则</el-radio-button></el-radio-group><div v-if="model.rename_mode==='smart'" class="rename-config"><div class="form-grid"><label>忽略前缀（每行一个）<el-input v-model="model.rename_ignore" type="textarea" :rows="3" placeholder="DMIT-US&#10;另一个入口前缀"/></label><label>改名模板<el-input v-model="model.rename_template"/><small class="field-help">可用：{index} {flag} {country} {name} {traffic} {reset} {source} {original}</small></label></div><div class="rename-preview"><label>输入示例<el-input v-model="renameSample"/></label><div><span>自动改名结果</span><b>{{renamePreview}}</b></div></div><p class="rename-note">流量固定识别 📊500.00GB，重置时间固定识别 ⌛25D；缺少的字段会自动省略。</p></div></section>
<section class="panel form-section"><div class="section-head"><span>04</span><div><h2>客户端输出</h2><p>每个输出都有独立、固定的公开订阅地址。</p></div><el-button @click="addOutput"><Plus/>添加客户端</el-button></div><div class="structured-list outputs"><article v-for="(out,i) in model.outputs" :key="out.id||i"><div class="list-fields output-fields"><label>客户端<el-select v-model="out.client_type"><el-option v-for="(value,key) in store.types" :key="key" :label="value.label" :value="key"/></el-select></label><label>显示名称<el-input v-model="out.name"/></label><label>URL 标识<el-input v-model="out.slug"/></label><label>建议更新间隔<el-input-number v-model="out.update_interval_minutes" :min="5" :max="10080" controls-position="right"/></label></div><el-switch v-model="out.enabled"/><button class="icon-danger" @click="model.outputs.splice(i,1)"><Trash2/></button></article></div></section></div>
<aside class="editor-aside"><div class="panel sticky-card"><p class="eyebrow">FIXED POLICY</p><h3>大陆直连，其他代理</h3><div class="policy"><span>局域网 / 私有地址</span><b>DIRECT</b><span>中国大陆域名与 IP</span><b>DIRECT</b><span>其他流量</span><b>PROXY</b></div><p>PROXY 包含自动选择、DIRECT 和所有真实节点，可在 Clash Verge 中手动选择。</p></div></aside></div></section></template>
